import type { AudioTrack } from "../context/AudioContext";
import { weddingEvents } from "./weddingEvents";

/**
 * Section music
 * ------------------------------------------------------------------
 * One background track per section of the invitation. Whichever section
 * is in view owns the music — see src/hooks/useSectionMusic.ts.
 *
 * The four wedding functions take their clip straight from
 * src/config/weddingEvents.ts, so a function and its music are always
 * configured in one place.
 *
 * Files live in `public/audio` and are generated by `npm run generate:audio`.
 */

/** Ambient theme for the welcome screen and the invitation cover. */
export const invitationTrack: AudioTrack = {
  id: "invitation-theme",
  src: "/audio/invitation-theme.wav",
  title: "Invitation Theme",
  artist: "Original instrumental",
};

/** Romantic pair theme — the couple introduction. */
export const coupleTrack: AudioTrack = {
  id: "couple",
  src: "/audio/couple.wav",
  title: "Two Hearts",
  artist: "Original instrumental",
};

/** Expectant, ticking build-up for the countdown. */
export const countdownTrack: AudioTrack = {
  id: "countdown",
  src: "/audio/countdown.wav",
  title: "Counting Down",
  artist: "Original instrumental",
};

/** Nostalgic, reflective — the love story timeline. */
export const storyTrack: AudioTrack = {
  id: "story",
  src: "/audio/story.wav",
  title: "How We Met",
  artist: "Original instrumental",
};

/** Bright and lighthearted — the photo gallery. */
export const galleryTrack: AudioTrack = {
  id: "gallery",
  src: "/audio/gallery.wav",
  title: "Moments in Frame",
  artist: "Original instrumental",
};

/** Jubilant send-off shared by the venue, RSVP and thank-you sections. */
export const celebrationTrack: AudioTrack = {
  id: "celebration",
  src: "/audio/celebration.wav",
  title: "See You There",
  artist: "Original instrumental",
};

/** Section id -> background track. */
export const sectionMusic: Record<string, AudioTrack> = {
  home: invitationTrack,
  couple: coupleTrack,
  countdown: countdownTrack,
  ...Object.fromEntries(
    weddingEvents.map((event) => [
      event.id,
      {
        id: event.id,
        src: event.audioSrc,
        title: event.musicTitle,
        artist: event.musicArtist,
      } satisfies AudioTrack,
    ]),
  ),
  story: storyTrack,
  gallery: galleryTrack,
  venue: celebrationTrack,
  rsvp: celebrationTrack,
  thanks: celebrationTrack,
};

/**
 * Every scored section, in page order. The order matters: if two sections
 * share the middle of the viewport, the later one wins.
 */
export const musicSections: Array<{ id: string; track: AudioTrack }> = [
  "home",
  "couple",
  "countdown",
  "haldi",
  "mehendi",
  "sangeet",
  "wedding",
  "story",
  "gallery",
  "venue",
  "rsvp",
  "thanks",
].flatMap((id) => (sectionMusic[id] ? [{ id, track: sectionMusic[id] }] : []));
